import { NextResponse } from "next/server";
import { generateSitemaps } from "@/app/sitemap";

export const dynamic = "force-static";
export const revalidate = 86400; // Revalidate sitemap index once per day

const BASE_URL = "https://www.discountproducts.co.uk";

/**
 * Serves the static XML `<sitemapindex>` referencing all chunked `/sitemap/[id].xml`
 * sub-sitemaps generated by `src/app/sitemap.ts`. Also served transparently at `/sitemap.xml`
 * via `next.config.js` rewrite so existing Search Console submissions never 404.
 */
export async function GET(): Promise<NextResponse> {
  const sitemaps = await generateSitemaps();
  const lastmod = new Date().toISOString();

  const entries = sitemaps
    .map(
      ({ id }) =>
        `  <sitemap>\n    <loc>${BASE_URL}/sitemap/${id}.xml</loc>\n    <lastmod>${lastmod}</lastmod>\n  </sitemap>`
    )
    .join("\n");

  const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${entries}\n</sitemapindex>\n`;

  return new NextResponse(xml, {
    status: 200,
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=0, s-maxage=86400, stale-while-revalidate=86400",
    },
  });
}
